using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private string? method, path, contentType, body;
    private int status = 200;
    private string reply = """{"status":"approved"}""";

    public HttpPaymentGatewayTests()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        var prefix = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(prefix);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(prefix) };
        _ = Task.Run(Serve);
    }

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext ctx;
            try { ctx = await listener.GetContextAsync(); } catch { return; }
            using (var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8)) body = await reader.ReadToEndAsync();
            method = ctx.Request.HttpMethod;
            path = ctx.Request.Url!.AbsolutePath;
            contentType = ctx.Request.ContentType;
            var bytes = Encoding.UTF8.GetBytes(reply);
            ctx.Response.StatusCode = status;
            ctx.Response.ContentType = "application/json";
            await ctx.Response.OutputStream.WriteAsync(bytes);
            ctx.Response.Close();
        }
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

    [Fact]
    public async Task The_request_is_a_json_post_with_reference_amount_and_currency()
    {
        await Authorize();

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var doc = JsonDocument.Parse(body!);
        var root = doc.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_approved()
    {
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_declined()
    {
        reply = """{"status":"declined"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        reply = """{"id":"x1","status":"approved","risk":{"score":3}}""";
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_refused_payment_402_is_declined_not_an_error()
    {
        status = 402;
        reply = """{"error":"card_refused"}""";
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData("{}")]
    [InlineData("""{"status":"unknown"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_an_approval_is_never_approved(string answer)
    {
        reply = answer;
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_surface_as_errors(int code)
    {
        status = code;
        reply = """{"status":"approved"}""";
        await Assert.ThrowsAsync<HttpRequestException>(Authorize);
    }

    [Fact]
    public async Task A_non_json_answer_surfaces_as_an_error()
    {
        reply = "<html>oops</html>";
        await Assert.ThrowsAnyAsync<JsonException>(Authorize);
    }

    public void Dispose()
    {
        listener.Close();
        client.Dispose();
    }
}
